/* @autogenerated */
package net.civeira.phylax.features.oauth.session.infrastructure;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;
import java.time.temporal.ChronoUnit;

import javax.sql.DataSource;

import io.quarkus.scheduler.Scheduled;
import io.quarkus.scheduler.Scheduled.ConcurrentExecution;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class OAuthCleanupScheduler {

  private static final int BATCH_LIMIT = 1000;

  private final DataSource source;

  @Scheduled(cron = "${oauth.cleanup.expired.cron:0 0 * * * ?}",
      concurrentExecution = ConcurrentExecution.SKIP)
  public void cleanExpired() {
    log.debug("Running OAuth expired-row cleanup");
    deleteInBatches("DELETE FROM _oauth_revoked_jti WHERE expires_at < ? LIMIT " + BATCH_LIMIT);
    deleteOnce("DELETE FROM _oauth_device_codes WHERE expires_at < ?");
    deleteOnce("DELETE FROM _oauth_magic_link WHERE expires_at < ?");
    deleteOnce("DELETE FROM _oauth_par_request WHERE expires_at < ?");
    deleteOnce("DELETE FROM _oauth_webauthn_challenge WHERE expires_at < ?");
    deleteOnce("DELETE FROM _oauth_delegated_state WHERE expires_at < ?");
  }

  @Scheduled(cron = "${oauth.cleanup.audit-log.cron:0 0 4 * * ?}",
      concurrentExecution = ConcurrentExecution.SKIP)
  public void cleanAuditLog() {
    log.debug("Running OAuth audit log cleanup");
    Timestamp cutoff =
        Timestamp.from(Instant.now().minus(90, ChronoUnit.DAYS));
    try (Connection conn = source.getConnection();
        PreparedStatement stmt =
            conn.prepareStatement("DELETE FROM _oauth_audit_log WHERE created_at < ?")) {
      stmt.setTimestamp(1, cutoff);
      int deleted = stmt.executeUpdate();
      log.debug("Audit log cleanup: {} rows deleted", deleted);
    } catch (SQLException e) {
      log.error("Audit log cleanup failed", e);
    }
  }

  private void deleteOnce(String sql) {
    Timestamp now = Timestamp.from(Instant.now());
    try (Connection conn = source.getConnection();
        PreparedStatement stmt = conn.prepareStatement(sql)) {
      stmt.setTimestamp(1, now);
      int deleted = stmt.executeUpdate();
      log.debug("Cleanup [{}]: {} rows deleted", sql, deleted);
    } catch (SQLException e) {
      log.error("Cleanup failed [{}]", sql, e);
    }
  }

  private void deleteInBatches(String sql) {
    Timestamp now = Timestamp.from(Instant.now());
    int deleted;
    int total = 0;
    do {
      try (Connection conn = source.getConnection();
          PreparedStatement stmt = conn.prepareStatement(sql)) {
        stmt.setTimestamp(1, now);
        deleted = stmt.executeUpdate();
        total += deleted;
      } catch (SQLException e) {
        log.error("Batch cleanup failed [{}]", sql, e);
        return;
      }
    } while (deleted == BATCH_LIMIT);
    log.debug("Batch cleanup [{}]: {} rows deleted", sql, total);
  }
}
